style.css:
/*
 * High Contrast Dark Theme
 * Author: Your Name
 * Version: 1.0
 */

/* Global styles */
body, html {
    background-color: #000 !important;
    color: #fff !important;
}

/* Links */
a {
    color: #0f0 !important; /* Bright green for high contrast */
}

a:visited {
    color: #0a0 !important; /* Darker green for visited links */
}

/* Headings */
h1, h2, h3, h4, h5, h6 {
    color: #fff !important;
    border-bottom: 1px solid #fff !important; /* White bottom border for headings */
}

/* Tables */
table, th, td {
    border: 1px solid #fff !important; /* White borders for tables */
}

th {
    background-color: #333 !important; /* Dark gray background for table headers */
}

/* Forms */
input, textarea, select, button {
    background-color: #333 !important; /* Dark gray background for form elements */
    color: #fff !important; /* White text for form elements */
    border: 1px solid #fff !important; /* White borders for form elements */
}

/* Code blocks */
pre, code {
    background-color: #333 !important; /* Dark gray background for code blocks */
    color: #fff !important; /* White text for code blocks */
    border: 1px solid #fff !important; /* White borders for code blocks */
}
